import os, json, gzip, base64, re, psycopg2, psycopg2.extras

DATA = """"""

def parse_date(v):
    if not v or not v.strip():
        return ''
    v = v.strip()
    if re.match(r'^\d{4}-\d{2}-\d{2}$', v):
        return v
    from datetime import datetime
    for fmt in ['%d-%b-%Y', '%d/%m/%Y', '%m/%d/%Y']:
        try:
            return datetime.strptime(v, fmt).strftime('%Y-%m-%d')
        except ValueError:
            continue
    return v

def extract_reg(candidate):
    if not candidate:
        return None
    parts = str(candidate).rsplit(' - ', 1)
    return parts[1].strip() if len(parts) == 2 and parts[1].strip() else None

def main():
    raw = gzip.decompress(base64.b64decode(DATA))
    rows = json.loads(raw)
    conn = psycopg2.connect(os.environ["DATABASE_URL"], cursor_factory=psycopg2.extras.RealDictCursor)
    cur = conn.cursor()
    imported = updated = skipped = 0
    for row in rows:
        candidate = row.get("Candidate Name", "").strip()
        reg_num = extract_reg(candidate)
        if not reg_num:
            skipped += 1
            continue
        cur.execute("SELECT registration_number FROM plab_clients WHERE registration_number = %s", (reg_num,))
        if not cur.fetchone():
            skipped += 1
            continue
        event_type = row.get("Event Type", "").strip()
        event_name = row.get("Webinar and Event Name", "").strip()
        start_date = parse_date(row.get("Start Date", ""))
        end_date = parse_date(row.get("End Date", ""))
        duration_raw = row.get("Duration (Days)", "")
        duration_days = ""
        if duration_raw:
            try:
                duration_days = str(int(float(str(duration_raw))))
            except (ValueError, TypeError):
                duration_days = str(duration_raw).strip()
        event_value = row.get("Event Value", "").strip()
        cpd_raw = row.get("CPD Points", "")
        cpd_points = ""
        if cpd_raw:
            try:
                cpd_points = str(int(float(str(cpd_raw))))
            except (ValueError, TypeError):
                cpd_points = str(cpd_raw).strip()
        participation_type = row.get("Conference Participation Type", "").strip()
        notes = row.get("Notes", "").strip()
        mobile = row.get("Mobile Number", "").strip()
        candidate_email = row.get("Candidate Email", "").strip()

        cur.execute(
            "SELECT id FROM ops_webinars_conferences WHERE registration_number = %s AND COALESCE(event_name,'') = %s AND COALESCE(start_date,'') = %s",
            (reg_num, event_name, start_date)
        )
        exists = cur.fetchone()
        if exists:
            cur.execute("""UPDATE ops_webinars_conferences SET
                event_type=%s, end_date=%s, duration_days=%s, event_value=%s,
                cpd_points=%s, participation_type=%s, notes=%s,
                mobile_number=%s, candidate_email=%s WHERE id=%s""", (
                event_type, end_date, duration_days, event_value,
                cpd_points, participation_type, notes,
                mobile, candidate_email, exists["id"]
            ))
            updated += 1
        else:
            cur.execute("""INSERT INTO ops_webinars_conferences (
                registration_number, event_type, start_date, end_date, duration_days,
                event_value, cpd_points, event_name, participation_type,
                notes, mobile_number, candidate_email, created_by
            ) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""", (
                reg_num, event_type, start_date, end_date, duration_days,
                event_value, cpd_points, event_name, participation_type,
                notes, mobile, candidate_email, 0
            ))
            imported += 1
    conn.commit()
    cur.close()
    conn.close()
    print(f"Webinars & Conferences: {imported} new, {updated} updated, {skipped} skipped")
    print(f"Total Events: {imported + updated + skipped}")

if __name__ == "__main__":
    main()
